/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The program receives a single command‑line argument that is expected
 * to be a Roman numeral (case‑insensitive).  If the argument is a
 * *valid* Roman numeral in the range 1 … 3999 the program prints the
 * corresponding integer value followed by a newline.  Otherwise it
 * prints the literal string "INVALID" (also followed by a newline).
 *
 * Validation is performed exactly as the original binary did:
 *   1. The argument must be present, non‑empty and at most 63 characters.
 *   2. The argument is converted to upper‑case.
 *   3. The value is obtained by greedily matching the standard Roman
 *      symbols in descending order.
 *   4. The canonical representation of the computed value is rebuilt
 *      and compared with the upper‑cased input; a mismatch means the
 *      input was not a *standard* Roman numeral.
 *   5. The resulting value must not exceed 3999.
 *
 * The implementation follows the same algorithmic steps but is
 * written in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const char *SYMS[] = {
    "M",  "CM", "D",  "CD", "C",
    "XC", "L",  "XL", "X",  "IX",
    "V",  "IV", "I"
};

static const int VALUES[] = {
    1000, 900, 500, 400, 100,
     90,   50,  40,  10,   9,
      5,    4,   1
};

#define SYM_COUNT (sizeof(SYMS) / sizeof(SYMS[0]))
#define MAX_INPUT_LEN 63

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* 1. basic length checks */
    if (len == 0 || len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* 2. build an upper‑case copy */
    char upper[MAX_INPUT_LEN + 1];
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        upper[i] = (char)toupper(c);
    }
    upper[len] = '\0';

    /* 3. greedy parsing to obtain the integer value */
    int total = 0;
    size_t pos = 0;               /* current position in upper */
    for (size_t i = 0; i < SYM_COUNT; ++i) {
        const char *sym = SYMS[i];
        size_t sym_len = strlen(sym);
        while (pos + sym_len <= len &&
               strncmp(upper + pos, sym, sym_len) == 0) {
            total += VALUES[i];
            pos += sym_len;
        }
    }

    /* if we could not consume the whole input, it is invalid */
    if (pos != len) {
        puts("INVALID");
        return 0;
    }

    /* 4. value must be within the conventional range */
    if (total > 3999) {
        puts("INVALID");
        return 0;
    }

    /* 5. rebuild the canonical Roman numeral for the computed value */
    char canonical[MAX_INPUT_LEN + 1];
    size_t canon_len = 0;
    int remaining = total;

    for (size_t i = 0; i < SYM_COUNT; ++i) {
        while (remaining >= VALUES[i]) {
            const char *sym = SYMS[i];
            size_t sym_len = strlen(sym);
            memcpy(canonical + canon_len, sym, sym_len);
            canon_len += sym_len;
            remaining -= VALUES[i];
        }
    }
    canonical[canon_len] = '\0';

    /* 6. final validation – the input must match the canonical form */
    if (strcmp(canonical, upper) != 0) {
        puts("INVALID");
        return 0;
    }

    /* 7. success – print the integer value */
    printf("%d\n", total);
    return 0;
}
